&lt;p style=&quot;text-align:start&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Kuvvetlenmek başka, şişmanlamak başka! Evet rakamlar b&amp;uuml;y&amp;uuml;yor, şişiyor ama &amp;uuml;lke kuvvetlenmiyor.&amp;rdquo;&lt;a name=&quot;_Toc215968218&quot;&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

